#!/usr/bin/env python3
# AI : push repo .env → Vercel; pull Supabase API keys → .env (dashboard keys are generated by Supabase, not uploaded).
from __future__ import annotations

import argparse
import json
import os
import re
import subprocess
import sys
import urllib.error
import urllib.request
from pathlib import Path
from typing import Literal

ROOT = Path(__file__).resolve().parent.parent
ENV_FILE = ROOT / ".env"
LINKED_PROJECT = ROOT / "supabase" / ".temp" / "linked-project.json"
DEFAULT_PROJECT_REF = "tyorbhyokwlkuuhswscp"
VERCEL_API = "https://api.vercel.com"

# AI : Spine app (combined_full_stack on Vercel) — keys the hosted app reads at runtime/build.
SPINE_ENV_KEYS: tuple[str, ...] = (
    "NEXT_PUBLIC_SUPABASE_URL",
    "NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY",
    "SUPABASE_URL",
    "SUPABASE_ANON_KEY",
    "SUPABASE_SERVICE_ROLE_KEY",
    "OPENROUTER_API_KEY",
    "LANDING_DEMO_PROXY_SECRET",
    "LANDING_DEMO_IP_SALT",
    "UPSTASH_REDIS_REST_URL",
    "UPSTASH_REDIS_REST_TOKEN",
    "NEXT_PUBLIC_STRIPE_ENABLED",
    "NEXT_PUBLIC_STRIPE_PUBLISHABLE_KEY",
    "STRIPE_SECRET_KEY",
    "STRIPE_WEBHOOK_SECRET",
)

# AI : landing_page Vercel project — proxies demo traffic to Spine.
LANDING_ENV_KEYS: tuple[str, ...] = (
    "LANDING_DEMO_PROXY_SECRET",
    "LANDING_DEMO_IP_SALT",
)

LANDING_DEFAULTS: dict[str, str] = {
    "SPINE_API_URL": "https://www.spine-ai-app.dev",
}


class UploadError(RuntimeError):
    pass


def log(msg: str) -> None:
    print(f"[upload-env] {msg}", flush=True)


def read_env_file(path: Path) -> dict[str, str]:
    if not path.exists():
        return {}
    values: dict[str, str] = {}
    for line in path.read_text(encoding="utf-8").splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith("#") or "=" not in stripped:
            continue
        key, raw = stripped.split("=", 1)
        key = key.strip()
        value = raw.strip()
        if len(value) >= 2 and value[0] == value[-1] == '"':
            value = value[1:-1]
        values[key] = value
    return values


def upsert_env(path: Path, updates: dict[str, str]) -> None:
    lines: list[str] = []
    remaining = dict(updates)
    if path.exists():
        for line in path.read_text(encoding="utf-8").splitlines():
            stripped = line.strip()
            if not stripped or stripped.startswith("#") or "=" not in stripped:
                lines.append(line)
                continue
            key = stripped.split("=", 1)[0].strip()
            if key in remaining:
                lines.append(f'{key}="{remaining[key]}"')
                del remaining[key]
            else:
                lines.append(line)
    for key in sorted(remaining):
        lines.append(f'{key}="{remaining[key]}"')
    path.write_text("\n".join(lines).rstrip() + "\n", encoding="utf-8")


def project_ref_from_env(env: dict[str, str]) -> str:
    url = env.get("NEXT_PUBLIC_SUPABASE_URL") or env.get("SUPABASE_URL") or ""
    match = re.search(r"https://([a-z0-9]+)\.supabase\.co", url)
    if match:
        return match.group(1)
    if LINKED_PROJECT.exists():
        data = json.loads(LINKED_PROJECT.read_text(encoding="utf-8"))
        ref = data.get("ref")
        if ref:
            return str(ref)
    return DEFAULT_PROJECT_REF


def supabase_cmd() -> list[str]:
    from shutil import which

    if which("supabase"):
        return ["supabase"]
    return ["npx", "--yes", "supabase"]


def pull_supabase_keys(*, project_ref: str, dry_run: bool) -> dict[str, str]:
    proc = subprocess.run(
        [*supabase_cmd(), "projects", "api-keys", "--project-ref", project_ref, "-o", "json"],
        cwd=ROOT,
        text=True,
        capture_output=True,
        check=False,
    )
    if proc.returncode != 0:
        raise UploadError(
            "supabase projects api-keys failed — run `supabase login` first.\n"
            + (proc.stderr.strip() or proc.stdout.strip())
        )
    keys = json.loads(proc.stdout)
    publishable = ""
    secret = ""
    anon = ""
    service = ""
    for row in keys:
        kind = row.get("type")
        value = row.get("api_key") or ""
        if kind == "publishable" and value and "····" not in value:
            publishable = value
        elif kind == "secret" and value and "····" not in value:
            secret = value
        elif kind == "legacy" and row.get("name") == "anon":
            anon = value
        elif kind == "legacy" and row.get("name") == "service_role":
            service = value

    if not publishable and anon:
        publishable = anon
    if not secret and service:
        secret = service

    api_url = f"https://{project_ref}.supabase.co"
    updates = {
        "SUPABASE_URL": api_url,
        "NEXT_PUBLIC_SUPABASE_URL": api_url,
        "SUPABASE_ANON_KEY": publishable or anon,
        "NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY": publishable or anon,
        "SUPABASE_SERVICE_ROLE_KEY": secret or service,
    }
    if not updates["NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY"]:
        raise UploadError(
            "could not read publishable/anon key — create keys in Supabase dashboard "
            f"(https://supabase.com/dashboard/project/{project_ref}/settings/api-keys) "
            "or use Management API to enable publishable + secret keys."
        )
    if dry_run:
        log(f"would write Supabase keys to {ENV_FILE.name} (project {project_ref})")
        for key in updates:
            log(f"  {key}=***")
        return updates
    upsert_env(ENV_FILE, updates)
    log(f"synced Supabase API keys into {ENV_FILE.name} (project {project_ref})")
    return updates


def vercel_request(
    method: str,
    path: str,
    token: str,
    *,
    body: dict | None = None,
    team_id: str | None = None,
) -> object:
    url = f"{VERCEL_API}{path}"
    if team_id:
        sep = "&" if "?" in url else "?"
        url = f"{url}{sep}teamId={team_id}"
    data = None
    headers = {"Authorization": f"Bearer {token}"}
    if body is not None:
        data = json.dumps(body).encode("utf-8")
        headers["Content-Type"] = "application/json"
    req = urllib.request.Request(url, data=data, headers=headers, method=method)
    try:
        with urllib.request.urlopen(req, timeout=60) as res:
            raw = res.read().decode("utf-8")
            return json.loads(raw) if raw else {}
    except urllib.error.HTTPError as err:
        detail = err.read().decode("utf-8", errors="replace")
        raise UploadError(f"Vercel API {method} {path} → {err.code}: {detail}") from err


def list_vercel_env(project: str, token: str, team_id: str | None) -> list[dict]:
    data = vercel_request("GET", f"/v9/projects/{project}/env", token, team_id=team_id)
    envs = data.get("envs") if isinstance(data, dict) else None
    return envs if isinstance(envs, list) else []


def delete_vercel_env(project: str, env_id: str, token: str, team_id: str | None) -> None:
    vercel_request("DELETE", f"/v9/projects/{project}/env/{env_id}", token, team_id=team_id)


def upsert_vercel_env(
    project: str,
    key: str,
    value: str,
    token: str,
    team_id: str | None,
    *,
    dry_run: bool,
) -> None:
    env_type: Literal["plain", "encrypted"] = "plain" if key.startswith("NEXT_PUBLIC_") else "encrypted"
    targets = ["production", "preview", "development"]
    existing = [row for row in list_vercel_env(project, token, team_id) if row.get("key") == key]
    if dry_run:
        action = "update" if existing else "create"
        log(f"  [{project}] would {action} {key} ({env_type})")
        return
    for row in existing:
        env_id = row.get("id")
        if env_id:
            delete_vercel_env(project, str(env_id), token, team_id)
    vercel_request(
        "POST",
        f"/v10/projects/{project}/env",
        token,
        body={"key": key, "value": value, "type": env_type, "target": targets},
        team_id=team_id,
    )
    log(f"  [{project}] set {key}")


def push_vercel_project(
    project: str,
    keys: tuple[str, ...],
    env: dict[str, str],
    token: str,
    team_id: str | None,
    *,
    extras: dict[str, str] | None = None,
    dry_run: bool,
) -> None:
    log(f"uploading to Vercel project {project!r}…")
    merged = dict(extras or {})
    for key in keys:
        val = env.get(key, "").strip()
        if val:
            merged[key] = val
    missing = [k for k in keys if k not in merged or not merged[k]]
    if missing:
        log(f"  skipping missing keys: {', '.join(missing)}")
    for key, value in merged.items():
        if not value:
            continue
        upsert_vercel_env(project, key, value, token, team_id, dry_run=dry_run)


def cmd_pull_supabase(args: argparse.Namespace) -> None:
    env = read_env_file(ENV_FILE)
    ref = args.project_ref or project_ref_from_env(env)
    pull_supabase_keys(project_ref=ref, dry_run=args.dry_run)


def cmd_push_vercel(args: argparse.Namespace) -> None:
    token = os.environ.get("VERCEL_TOKEN", "").strip()
    if not token:
        raise UploadError(
            "VERCEL_TOKEN missing — create one at https://vercel.com/account/tokens "
            "and export it before running this script."
        )
    env = read_env_file(ENV_FILE)
    if not env:
        raise UploadError(f"{ENV_FILE} not found or empty")
    team_id = args.team_id or os.environ.get("VERCEL_TEAM_ID")
    spine = args.spine_project or os.environ.get("VERCEL_SPINE_PROJECT")
    landing = args.landing_project or os.environ.get("VERCEL_LANDING_PROJECT")
    if not spine:
        raise UploadError("pass --spine-project or set VERCEL_SPINE_PROJECT")
    push_vercel_project(
        spine,
        SPINE_ENV_KEYS,
        env,
        token,
        team_id,
        dry_run=args.dry_run,
    )
    if args.landing and landing:
        push_vercel_project(
            landing,
            LANDING_ENV_KEYS,
            env,
            token,
            team_id,
            extras=LANDING_DEFAULTS,
            dry_run=args.dry_run,
        )
    elif args.landing and not landing:
        log("  skipped landing — pass --landing-project or set VERCEL_LANDING_PROJECT")
    if not args.dry_run:
        log("done — redeploy both Vercel projects so new env vars take effect.")


def cmd_all(args: argparse.Namespace) -> None:
    cmd_pull_supabase(args)
    cmd_push_vercel(args)


def add_common_flags(parser: argparse.ArgumentParser) -> None:
    parser.add_argument(
        "--dry-run",
        action="store_true",
        help="print actions without writing .env or calling Vercel",
    )
    parser.add_argument(
        "--project-ref",
        help=f"Supabase project ref (default: from .env URL or {DEFAULT_PROJECT_REF})",
    )


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description=(
            "Sync hosted deploy env: pull Supabase API keys into .env, push .env to Vercel. "
            "Supabase dashboard API keys cannot be uploaded from local values — they are generated by Supabase."
        ),
    )
    sub = parser.add_subparsers(dest="command", required=True)

    pull = sub.add_parser(
        "pull-supabase",
        help="fetch API keys from linked Supabase project → repo .env",
    )
    add_common_flags(pull)

    vercel = sub.add_parser("push-vercel", help="upload .env values → Vercel project(s)")
    add_common_flags(vercel)
    vercel.add_argument(
        "--spine-project",
        help="Vercel project name/id for combined_full_stack (or VERCEL_SPINE_PROJECT)",
    )
    vercel.add_argument(
        "--landing-project",
        help="Vercel project name/id for landing_page (or VERCEL_LANDING_PROJECT)",
    )
    vercel.add_argument("--team-id", help="Vercel team id (or VERCEL_TEAM_ID)")
    vercel.add_argument(
        "--landing",
        action="store_true",
        help="also push landing_page env vars",
    )

    all_cmd = sub.add_parser("all", help="pull-supabase then push-vercel (both projects)")
    add_common_flags(all_cmd)
    all_cmd.add_argument("--spine-project")
    all_cmd.add_argument("--landing-project")
    all_cmd.add_argument("--team-id")
    all_cmd.set_defaults(landing=True)
    return parser


def main() -> int:
    parser = build_parser()
    args = parser.parse_args()
    handlers = {
        "pull-supabase": cmd_pull_supabase,
        "push-vercel": cmd_push_vercel,
        "all": cmd_all,
    }
    try:
        handlers[args.command](args)
    except UploadError as err:
        print(f"[upload-env] ERROR: {err}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
